#include <stdlib.h>
#include <string.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 72
#define NC 256

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ld8(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void st8(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                   float *restrict C, int ldc, int acc, int mr, int nr)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(Bp + k * NR);
        v8 b1 = *(const v8 *)(Bp + k * NR + 8);
        const float *a = Ap + k * MR;
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
    }

    if (mr == MR && nr == NR) {
#define STROW(i, x0, x1) do { float *cp = C + (i) * ldc; \
        if (acc) { x0 += ld8(cp); x1 += ld8(cp + 8); } \
        st8(cp, x0); st8(cp + 8, x1); } while (0)
        STROW(0, c00, c01); STROW(1, c10, c11); STROW(2, c20, c21);
        STROW(3, c30, c31); STROW(4, c40, c41); STROW(5, c50, c51);
#undef STROW
    } else {
        float t[MR * NR] __attribute__((aligned(64)));
        st8(t + 0 * NR, c00); st8(t + 0 * NR + 8, c01);
        st8(t + 1 * NR, c10); st8(t + 1 * NR + 8, c11);
        st8(t + 2 * NR, c20); st8(t + 2 * NR + 8, c21);
        st8(t + 3 * NR, c30); st8(t + 3 * NR + 8, c31);
        st8(t + 4 * NR, c40); st8(t + 4 * NR + 8, c41);
        st8(t + 5 * NR, c50); st8(t + 5 * NR + 8, c51);
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (acc) C[i * ldc + j] += t[i * NR + j];
                else     C[i * ldc + j]  = t[i * NR + j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int np = (n + NR - 1) / NR;
    size_t bsz = (size_t)np * NR * KC * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = aligned_alloc(64, bsz);

    int nic = (n + MC - 1) / MC;
    int njc = (n + NC - 1) / NC;
    int ntasks = nic * njc;

    #pragma omp parallel
    {
        float *Ap = aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc > 0;

            #pragma omp for schedule(static)
            for (int jp = 0; jp < np; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int col0 = jp * NR;
                int w = n - col0 < NR ? n - col0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + col0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < w; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

            #pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntasks; t++) {
                int ib = t / njc, jb = t % njc;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NC;
                int nc = n - jc < NC ? n - jc : NC;

                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)ir * kc;
                    for (int i = 0; i < MR; i++) {
                        int row = ic + ir + i;
                        if (ir + i < mc) {
                            const float *src = A + (size_t)row * n + pc;
                            for (int k = 0; k < kc; k++) dst[k * MR + i] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + i] = 0.0f;
                        }
                    }
                }

                for (int jr = 0; jr < nc; jr += NR) {
                    int col = jc + jr;
                    int nr = n - col < NR ? n - col : NR;
                    const float *bp = Bp + (size_t)(col / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(ic + ir) * n + col, n, acc, mr, nr);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
